<?php
namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage3; class oneindex extends cloudStorage3 { var $cookie = null; var $args; public function init() { $this->custom_upload_dir = $this->options->cloud_storage_oneindex_custom_upload_dir; $this->folder = $this->options->cloud_storage_oneindex_folder; $this->homepage = $this->options->cloud_storage_oneindex_homepage; $this->domain = $this->options->cloud_storage_oneindex_domain; $this->password = $this->options->cloud_storage_oneindex_password; $this->host = parse_url($this->homepage, PHP_URL_HOST); $this->sync_delete = $this->options->cloud_storage_oneindex_sync_delete; $this->silent_scanning = $this->options->cloud_storage_oneindex_silent_scanning; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_oneindex_delete_attachment_after_synced; add_filter( 'qqworld-collector-cloud-storage-settings', array($this, 'cloud_storage_settings') ); } public function cloud_storage_settings($values) { if (isset($values[$this->guid])) { $values[$this->guid]['homepage'] = preg_replace('/\/*$/i', '', trim($values[$this->guid]['homepage'])); if ($values[$this->guid]['homepage']) $this->create_table(); } return $values; } public function access_service() { if ($this->enabled && $this->is_current && !$this->accessed) { if ($this->password) { $this->cookie = get_transient( 'qqworld-collector-cloud-storage-oneindex-cookies' ); if ($this->cookie) { $this->accessed = true; $this->args = array( 'sslverify' => false, 'headers' => array( 'Content-Type' => 'application/x-www-form-urlencoded', 'Cookie' => $this->cookie ) ); return; } $this->cookie = apply_filters( 'qqworld-collector-cloud-storage-oneindex-login', '', $this ); if ($this->cookie) { $this->accessed = true; $this->args = array( 'sslverify' => false, 'headers' => array( 'content-type' => 'application/x-www-form-urlencoded', 'Cookie' => $this->cookie ) ); set_transient( 'qqworld-collector-cloud-storage-oneindex-cookies', $this->cookie, 60 ); } } } } public function is_object_exist($destination_path) { $destination_path = preg_replace('/^\/*/i', '', $destination_path); $this->access_service(); $file_name = strstr($destination_path, '/') === false ? $destination_path : basename($destination_path); $path = strstr($destination_path, '/') === false ? '' : dirname($destination_path); $url = $this->homepage . '/' . $path; $response = wp_remote_get($url, $this->args); $response_code = wp_remote_retrieve_response_code($response); if (in_array($response_code, array(200, 201))) { $body = wp_remote_retrieve_body($response); $preg = preg_match_all('/data-sort-name="'.$this->encode_pattern($file_name).'"[\s\S]*?id="(\w*?)"/i', $body, $matches); if ($preg) { return true; } } else { $response_message = wp_remote_retrieve_response_message($response); do_action( 'qqworld-collector-log', $this->log_id, 'OneIndex Query Items before Check Object Exists Request Error:', $url . ' (' . $response_code . ', ' . $response_message . ')' ); } return false; } public function make_dir($path) { $response = wp_remote_head($this->homepage . '/' . $path); $response_code = wp_remote_retrieve_response_code($response); if ($response_code == 404) { $paths = array_filter(explode('/', $path)); $url = $this->homepage; foreach ($paths as $path) { $response = wp_remote_head($url . '/' . $path); $response_code = wp_remote_retrieve_response_code($response); if ($response_code == 404) { $dir_args = $this->args; $dir_args['body'] = array( 'foldername' => $path, 'uploadurl' => $url . '/#mdui-dialog' ); $response = wp_remote_post($this->homepage.'/?/create_folder', $dir_args); } $url .= '/' . $path; } } } public function upload($destination_path, $source_path) { if (!file_exists($source_path) || !filesize($source_path)) return false; $destination_path = preg_replace('/^\//', '', $destination_path); $this->access_service(); $external_link = apply_filters( 'qqworld-collector-cloud-storage-oneindex-upload', '', $destination_path, $source_path, $this ); if ($external_link) return $external_link; return false; } public function delete_object($object) { $object = preg_replace('/^\/*/i', '', $object); $this->access_service(); $path = strstr($object, '/') === false ? '' : dirname($object); $file_name = strstr($object, '/') === false ? $object : basename($object); $url = $this->homepage . '/' . $path; $response = wp_remote_get($url, $this->args); $response_code = wp_remote_retrieve_response_code($response); if ($response_code == 200) { $body = wp_remote_retrieve_body($response); $preg = preg_match_all('/data-sort-name="'.$this->encode_pattern($file_name).'"[\s\S]*?id="(\w*?)"/i', $body, $matches); if ($preg) { foreach ($matches[1] as $term_id) { $url = $this->homepage . '/?/deleteitems'; $delete_args = $this->args; $delete_args['body'] = '["'.$term_id.'"]'; $response = wp_remote_post($url, $delete_args); $body = wp_remote_retrieve_body($response); $response_code = wp_remote_retrieve_response_code($response); if ($response_code == 200) { return true; } else { $response_message = wp_remote_retrieve_response_message($response); do_action( 'qqworld-collector-log', $this->log_id, 'OneIndex Delete Request Error:', $object . ' (' . $response_code . ', ' . $response_message . ')' ); } break; } } } else { $response_message = wp_remote_retrieve_response_message($response); do_action( 'qqworld-collector-log', $this->log_id, 'OneIndex Query Items before Delete Request Error:', $url . ' (' . $response_code . ', ' . $response_message . ')' ); } return false; } public function add_form_fields() { require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage3.php'; } public function add_could_storage_form($guid) { $this->access_service(); require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'.php'; } } ?>